from pathlib import Path
import json,html
P=Path(__file__).parent
root=P.parents[3]
h=json.loads((root/'src/i18n/locales/en/home.json').read_text())['hero']
logo='../../../brand/logo-hd-1761.png'
def brand():return f'<a class="brand" href="index.html"><img src="{logo}" alt="ai-memory brain logo"><span>ai-memory<span class="brand-sub">Memory infrastructure</span></span></a>'
nav='<nav aria-label="Main navigation"><a href="#how">How it works</a><a href="https://aimemory.sh/integrations/">Integrations</a><a href="https://aimemory.sh/security/">Security</a><a href="https://github.com/akitaonrails/ai-memory">GitHub ↗</a></nav>'
cta='<div class="actions"><a class="button primary" href="https://aimemory.sh/install/">Install ai-memory <span>↗</span></a><a class="button secondary" href="#how">See how it works <span>↓</span></a></div>'
lede=html.escape(h['lede'])
facts='<ul class="facts">'+''.join('<li>'+html.escape(x)+'</li>' for x in h['facts'])+'</ul>'
def brain(cls=''):
 return f'<img class="brain {cls}" src="{logo}" alt="A neural network becomes circuitry, with memory passing through a central chip">'
def diagram():
 return '''<svg class="flow" viewBox="0 0 900 180" role="img" aria-label="Your agents capture observations into a markdown wiki; the next session recalls that knowledge."><path d="M195 85H310V65H360M540 65H610V85H710" fill="none" stroke="currentColor" stroke-width="2"/><path d="m350 59 10 6-10 6m340 8 10 6-10 6" fill="none" stroke="currentColor" stroke-width="2"/><g fill="none" stroke="currentColor"><rect x="10" y="35" width="185" height="100"/><rect x="360" y="15" width="180" height="100"/><rect x="710" y="35" width="180" height="100"/></g><g fill="currentColor" font-size="20" text-anchor="middle"><text x="102" y="78">Your agents</text><text x="450" y="58">Markdown wiki</text><text x="800" y="78">Next session</text></g><g fill="currentColor" font-size="13" text-anchor="middle"><text x="102" y="105">Capture the work</text><text x="450" y="87">Files you own</text><text x="800" y="105">Recall the context</text><text x="450" y="158">One shared memory across agents and projects</text></g></svg>'''
def signal_diagram():
 return """<figure class="memory-circuit" aria-label="Agents capture observations into a markdown wiki, then the next session recalls the context."><div class="circuit-heading"><span>Capture → Retain → Recall</span><span>Memory path / 01</span></div><div class="circuit-path"><div class="circuit-node"><svg viewBox="0 0 160 140" aria-hidden="true"><path d="M25 32h86l24 24v60H25z" fill="#294552"/><path d="M25 32h86l24 24v60H25zM25 54h110" /><path d="m48 72 14 12-14 12m30 0h25" class="copper-stroke"/><circle cx="36" cy="43" r="2"/><circle cx="46" cy="43" r="2"/></svg><h3>Your agents</h3><p>Capture the work</p></div><div class="circuit-link" aria-hidden="true"><span></span></div><div class="circuit-node memory-core"><svg viewBox="0 0 160 140" aria-hidden="true"><path d="M49 8v20m21-20v20m21-20v20m21-20v20M49 112v20m21-20v20m21-20v20m21-20v20M17 44h22m-22 24h22m-22 24h22m82-48h22m-22 24h22m-22 24h22" class="copper-stroke"/><path d="M39 28h82v84H39z" fill="#dca574" class="chip"/><path d="M58 44h33l12 12v42H58zM91 44v14h12M68 70h25M68 81h25" class="chip-ink"/></svg><h3>Markdown wiki</h3><p>Files you own</p></div><div class="circuit-link" aria-hidden="true"><span></span></div><div class="circuit-node"><svg viewBox="0 0 160 140" aria-hidden="true"><path d="M25 32h86l24 24v60H25z" fill="#294552"/><path d="M25 32h86l24 24v60H25zM25 54h110"/><path d="m47 82 13 13 27-27m8 30h18" class="copper-stroke"/><circle cx="36" cy="43" r="2"/><circle cx="46" cy="43" r="2"/></svg><h3>Next session</h3><p>Recall the context</p></div></div><figcaption>One shared memory across agents and projects.</figcaption></figure>"""
def more(signal=False):
 return '''<section id="how" class="how"><div class="section-head"><span class="eyebrow">01 / Continuity</span><h2>The work continues.<br>The context comes with it.</h2></div><div class="diagram-wrap">'''+(signal_diagram() if signal else diagram())+'''</div><div class="details"><article><span class="index">01</span><h3>Capture as you work</h3><p>Lifecycle hooks record the session and strip secrets before storage. Your agent can search what earlier sessions learned.</p></article><article><span class="index">02</span><h3>Read what it remembers</h3><p>Memory lives in plain markdown pages backed by git. Browse the wiki, inspect its sources, and edit it yourself.</p></article><article><span class="index">03</span><h3>Pick up in another agent</h3><p>A handoff carries the open questions and next steps. Your next session starts with the project’s context.</p></article></div></section><section class="closing"><span class="eyebrow">Built for your machine</span><h2>Your memory.<br>Your files. Your server.</h2><div><p>Start locally with one binary. Add a model provider only when you want LLM features.</p><a class="button primary" href="https://aimemory.sh/install/">Get started <span>↗</span></a><a class="limits" href="https://aimemory.sh/security/">Read the security model and its limits ↗</a></div></section>'''
def end(letter):return f'<footer><a href="index.html">← Compare the three directions</a><span>Study {letter} / ai-memory / October 2026</span><a href="https://aimemory.sh/">Current website ↗</a></footer>'
def head(letter,title,fonts):return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>{letter} / {title} / ai-memory design study</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?{fonts}&display=swap" rel="stylesheet"><link rel="stylesheet" href="shared.css"><link rel="stylesheet" href="{letter.lower()}.css"></head><body class="{letter.lower()}"><div class="study"><a href="index.html">Design study / {letter} · {title}</a><div><a href="a.html">A</a><a href="b.html">B</a><a href="c.html">C</a></div></div>'''
a=head('A','Mnemonic Foundry','family=Barlow+Condensed:wght@500;600;700&family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500')+f'''<div class="shell"><header>{brand()}{nav}</header><main><section class="hero"><div class="hero-text"><div class="eyebrow">Persistent memory / Open source</div><h1>Switch agents.<br>Keep the<br><em>context.</em></h1><p class="lede">{lede}</p>{cta}</div><figure class="specimen"><div class="plate-head"><span>Neural / Digital</span><span>AM—01</span></div><div class="brain-stage">{brain()}<span class="vertical">Capture · Retain · Recall</span></div><figcaption><span class="square"></span> Context survives the session.</figcaption><div class="spec-row"><span>Storage</span><strong>Markdown + git</strong></div><div class="spec-row"><span>Deployment</span><strong>Your own machine</strong></div></figure></section>{facts}<div class="agent-strip"><span>One memory. Many agents.</span><strong>Claude Code</strong><strong>Codex</strong><strong>Cursor</strong><strong>Gemini CLI</strong><strong>OpenCode</strong></div>{more()}</main>{end('A')}</div></body></html>'''
b=head('B','Civic Archive','family=Space+Grotesk:wght@400;500;600;700&family=Source+Serif+4:opsz,wght@8..60,400;8..60,500&family=IBM+Plex+Mono:wght@400;500')+f'''<div class="shell"><header>{brand()}{nav}</header><main><section class="hero"><div class="archive-title"><span class="eyebrow">An open archive for machine intelligence</span><h1>What you learned<br>belongs to<br><em>what comes next.</em></h1></div><div class="archive-lower"><aside class="directory"><span class="eyebrow">In this system</span><a href="#how"><b>01</b> Capture</a><a href="#how"><b>02</b> Knowledge</a><a href="#how"><b>03</b> Continuity</a><span class="archive-stamp">Local storage<br>Human readable</span></aside><figure class="archive-brain">{brain()}<figcaption>01. The connection between sessions.</figcaption></figure><div class="intro"><h2>Switch agents.<br>Keep the context.</h2><p class="lede">{lede}</p>{cta}</div></div></section>{facts}{more()}</main>{end('B')}</div></body></html>'''
c=head('C','Signal Bureau','family=Manrope:wght@400;500;600;700;800&family=Chakra+Petch:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500')+f'''<div class="shell"><header>{brand()}{nav}</header><main><section class="hero"><div class="signal-top"><span class="eyebrow">Memory, across the network of your work.</span><span class="edition">Open source / Self-hosted</span></div><div class="signal-grid"><div class="hero-text"><h1>Different agents.<br><em>One memory.</em></h1><p class="lede">{lede}</p>{cta}{facts}</div><figure class="signal-brain"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div>{brain()}<figcaption>From neural connections<br>to durable knowledge.</figcaption></figure></div><div class="routing"><span>Claude Code<br><small>First session</small></span><i aria-hidden="true">↘</i><strong>ai-memory<br><small>Shared context</small></strong><i aria-hidden="true">↗</i><span>Codex<br><small>Next session</small></span></div></section>{more(signal=True)}</main>{end('C')}</div></body></html>'''
for letter,markup in [('a',a),('b',b),('c',c)]: (P/(letter+'.html')).write_text(markup)
